# Парсинг form-data в HTTP-запросе
import urllib.parse

def parse_form_urlencoded(body_bytes: bytes) -> dict:
    body_str = body_bytes.decode("utf-8")
    parsed = urllib.parse.parse_qs(body_str)
    return {k: v[0] if len(v) == 1 else v for k, v in parsed.items()}

# Пример:
res = parse_form_urlencoded(b"username=alex&grant_type=password")
print(res)  # {'username': 'alex', 'grant_type': 'password'}

