# Обработка CORS заголовков
ALLOWED_ORIGINS = {'https://frontend.com'}

def cors_middleware(environ: dict) -> dict:
    origin = environ.get('Origin', '')
    method = environ.get('REQUEST_METHOD', 'GET')
    headers = {}
    if origin in ALLOWED_ORIGINS:
        headers['Access-Control-Allow-Origin'] = origin
        headers['Access-Control-Allow-Credentials'] = 'true'
        if method == 'OPTIONS':
            headers['Access-Control-Allow-Methods'] = 'GET, POST, OPTIONS'
            headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
    return headers

h = cors_middleware({'Origin': 'https://frontend.com', 'REQUEST_METHOD': 'GET'})
print('CORS headers:', h)

