# Реализуйте IdempotentPaymentService
import hashlib
import json

class IdempotentPaymentService:
    def __init__(self):
        self._storage: dict[str, tuple[str, dict]] = {}
        self._next_tx_id = 1000

    def process_payment(self, idempotency_key: str, payload: dict) -> dict:
        if not idempotency_key:
            raise ValueError('Idempotency-Key обязателен')
        raw = json.dumps(payload, sort_keys=True).encode()
        payload_hash = hashlib.sha256(raw).hexdigest()

        if idempotency_key in self._storage:
            saved_hash, saved_resp = self._storage[idempotency_key]
            if saved_hash != payload_hash:
                return {'status': 'error', 'error': 'Key mismatch'}
            return saved_resp

        self._next_tx_id += 1
        response = {
            'tx_id': self._next_tx_id,
            'amount': payload.get('amount', 0),
            'status': 'success',
        }
        self._storage[idempotency_key] = (payload_hash, response)
        return response

svc = IdempotentPaymentService()
r1 = svc.process_payment('k1', {'amount': 500})
r2 = svc.process_payment('k1', {'amount': 500})
print('Result 1:', r1, '| Result 2:', r2)

