# WSGI Middleware замера времени ответа TimingMiddleware
import time

class TimingMiddleware:
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        start_time = time.perf_counter()

        def custom_start_response(status, response_headers, exc_info=None):
            duration = time.perf_counter() - start_time
            headers = list(response_headers)
            headers.append(('X-Process-Time', f'{duration:.4f}s'))
            return start_response(status, headers, exc_info)

        return self.app(environ, custom_start_response)

captured = {}
def mock_start_response(status, headers, exc_info=None):
    captured['status'] = status
    captured['headers'] = dict(headers)
    return lambda data: None

def simple_app(environ, start_response):
    start_response('200 OK', [('Content-Type', 'text/plain')])
    return [b'Hello WSGI']

if __name__ == '__main__':
    middleware = TimingMiddleware(simple_app)
    result = middleware({}, mock_start_response)
    print('Статус:', captured.get('status'))
    print('Заголовки:', captured.get('headers'))

