def diagnose_osi_layer(event: dict) -> dict:
    symptom = event.get('symptom', '').lower()
    if 'mac' in symptom or 'arp' in symptom or 'vlan' in symptom:
        return {'layer': 'L2', 'protocol': 'ARP', 'action': 'check_switch'}
    if 'ttl' in symptom or 'route' in symptom or 'unreachable' in symptom or 'icmp' in symptom:
        return {'layer': 'L3', 'protocol': 'IP', 'action': 'check_route'}
    if 'syn' in symptom or 'rst' in symptom or 'port' in symptom or 'udp' in symptom:
        return {'layer': 'L4', 'protocol': 'TCP', 'action': 'check_firewall'}
    if 'tls' in symptom or 'ssl' in symptom or 'certificate' in symptom:
        return {'layer': 'L6', 'protocol': 'TLS', 'action': 'check_cert'}
    if 'http' in symptom or 'dns' in symptom or '502' in symptom or '404' in symptom:
        proto = 'DNS' if 'dns' in symptom else 'HTTP'
        return {'layer': 'L7', 'protocol': proto, 'action': 'check_backend'}
    return {'layer': 'L1', 'protocol': 'UNKNOWN', 'action': 'check_cable'}

