class TCPConnection:
    def __init__(self):
        self.state = 'CLOSED'

    def handshake(self, client_isn: int, server_isn: int) -> list[dict]:
        packets = [
            {'flags': 'SYN', 'seq': client_isn, 'ack': 0},
            {'flags': 'SYN-ACK', 'seq': server_isn, 'ack': client_isn + 1},
            {'flags': 'ACK', 'seq': client_isn + 1, 'ack': server_isn + 1},
        ]
        self.state = 'ESTABLISHED'
        return packets

    def teardown(self, client_seq: int, server_seq: int) -> list[dict]:
        if self.state != 'ESTABLISHED':
            raise ValueError('Connection is not ESTABLISHED')
        packets = [
            {'flags': 'FIN', 'seq': client_seq, 'ack': server_seq},
            {'flags': 'ACK', 'seq': server_seq, 'ack': client_seq + 1},
            {'flags': 'FIN', 'seq': server_seq, 'ack': client_seq + 1},
            {'flags': 'ACK', 'seq': client_seq + 1, 'ack': server_seq + 1},
        ]
        self.state = 'TIME_WAIT'
        return packets

tests:
conn = TCPConnection()
assert conn.state == 'CLOSED'
hs = conn.handshake(100, 500)
assert len(hs) == 3
assert hs[0] == {'flags': 'SYN', 'seq': 100, 'ack': 0}
assert hs[1] == {'flags': 'SYN-ACK', 'seq': 500, 'ack': 101}
assert hs[2] == {'flags': 'ACK', 'seq': 101, 'ack': 501}
assert conn.state == 'ESTABLISHED'
td = conn.teardown(150, 520)
assert len(td) == 4
assert td[0] == {'flags': 'FIN', 'seq': 150, 'ack': 520}
assert td[1]['ack'] == 151 and td[3]['ack'] == 521
