def analyze_transport_metrics(events: list[dict], mtu: int = 1500, ip_hdr: int = 20, tcp_hdr: int = 20, syn_threshold: int = 3) -> dict:
    mss = mtu - ip_hdr - tcp_hdr
    if mss <= 0:
        raise ValueError('MSS must be positive')
    total_payload = sum(e.get('payload_bytes', 0) for e in events if e.get('type') == 'data')
    segments_needed = (total_payload + mss - 1) // mss if total_payload > 0 else 0

    hol_blocked = 0
    lost_seen = False
    for e in events:
        if e.get('type') == 'stream_packet':
            if lost_seen:
                hol_blocked += 1
            elif e.get('lost'):
                lost_seen = True

    half_open = set()
    for e in events:
        if e.get('type') == 'SYN':
            half_open.add(e['conn_id'])
        elif e.get('type') == 'ACK':
            half_open.discard(e['conn_id'])

    return {
        'mss': mss,
        'segments_needed': segments_needed,
        'hol_blocked': hol_blocked,
        'syn_flood_alert': len(half_open) > syn_threshold,
    }

