class DNSResolver:
    def __init__(self, records: dict):
        self.records = records
        self.cache = {}

    def resolve(self, domain: str, now: int = 0) -> list[str]:
        cached = self.cache.get(domain)
        if cached and now < cached['expires_at']:
            return list(cached['ips'])

        visited = set()
        curr = domain
        min_ttl = None
        while True:
            if curr in visited:
                raise ValueError(f'CNAME cycle detected at {curr}')
            visited.add(curr)
            rec = self.records.get(curr)
            if not rec:
                raise ValueError(f'NXDOMAIN: {curr}')
            ttl = rec.get('ttl', 60)
            min_ttl = ttl if min_ttl is None else min(min_ttl, ttl)
            if rec['type'] == 'A':
                val = rec['value']
                ips = list(val) if isinstance(val, list) else [val]
                self.cache[domain] = {'ips': ips, 'expires_at': now + min_ttl}
                return list(ips)
            if rec['type'] == 'CNAME':
                curr = rec['value']
            else:
                raise ValueError(f'Unsupported record type: {rec["type"]}')

