class BuggyDNSCache:
    def __init__(self):
        self._store = {}

    def put_a(self, domain: str, ips: list[str], ttl: int, now: int):
        self._store[domain] = {'status': 'OK', 'ips': list(ips), 'expires_at': now + ttl}

    def put_nxdomain(self, domain: str, neg_ttl: int, now: int):
        self._store[domain] = {'status': 'NXDOMAIN', 'ips': [], 'expires_at': now + neg_ttl}

    def get(self, domain: str, now: int):
        entry = self._store.get(domain)
        if not entry or now >= entry['expires_at']:
            self._store.pop(domain, None)
            return None
        if entry['status'] == 'NXDOMAIN':
            return {'status': 'NXDOMAIN'}
        ips = list(entry['ips'])
        if len(ips) > 1:
            entry['ips'] = entry['ips'][1:] + entry['ips'][:1]
        return {'status': 'OK', 'ips': ips}

