def dispatch_http_method(method: str, allowed_methods: list[str]) -> dict:
    m = method.upper()
    allowed = sorted(set(x.upper() for x in allowed_methods))
    allow_hdr = ', '.join(sorted(set(allowed + ['OPTIONS'])))
    if m == 'OPTIONS':
        return {'status': 204, 'headers': {'Allow': allow_hdr}, 'props': METHOD_PROPS['OPTIONS']}
    if m not in allowed:
        return {'status': 405, 'headers': {'Allow': ', '.join(allowed)}, 'props': METHOD_PROPS.get(m)}
    return {'status': 200, 'headers': {}, 'props': METHOD_PROPS[m]}

