def apply_resource_update(resource: dict, method: str, payload: dict, if_match: str | None = None) -> tuple[int, dict]:
    if if_match is not None and if_match != resource.get('etag'):
        return 412, dict(resource)

    m = method.upper()
    old_etag = resource.get('etag', 'v1')
    new_etag = f'v{int(old_etag[1:]) + 1}'

    if m == 'PUT':
        updated = {'id': resource['id'], 'etag': new_etag}
        for k, v in payload.items():
            if k not in ('id', 'etag') and v is not None:
                updated[k] = v
        return 200, updated

    if m == 'PATCH':
        updated = dict(resource)
        for k, v in payload.items():
            if k in ('id', 'etag'):
                continue
            if v is None:
                updated.pop(k, None)
            else:
                updated[k] = v
        updated['etag'] = new_etag
        return 200, updated

    return 405, dict(resource)

