from urllib.parse import urlparse

def follow_redirects(start_url: str, method: str, headers: dict, fetcher, max_hops: int = 5) -> dict:
    url = start_url
    cur_method = method.upper()
    cur_headers = dict(headers)
    visited = set()

    for hop in range(max_hops + 1):
        if url in visited:
            raise ValueError(f'Redirect loop detected at {url}')
        visited.add(url)
        resp = fetcher(url, cur_method, dict(cur_headers))
        status = resp['status']
        if status not in (301, 302, 303, 307, 308):
            return resp
        if hop == max_hops:
            raise ValueError('Too many redirects')
        loc = resp.get('headers', {}).get('Location')
        if not loc:
            raise ValueError('Redirect without Location')
        if urlparse(loc).netloc != urlparse(url).netloc:
            cur_headers.pop('Authorization', None)
        if status == 303 and cur_method not in ('GET', 'HEAD'):
            cur_method = 'GET'
        elif status in (301, 302) and cur_method == 'POST':
            cur_method = 'GET'
        url = loc
    raise ValueError('Too many redirects')

