def evaluate_http_cache(req_headers: dict, resource_etag: str, resource_body: str, cache_control: str, vary_headers: dict | None = None) -> dict:
    norm_req = {k.lower(): v for k, v in req_headers.items()}
    cc_parts = {p.strip().lower() for p in cache_control.split(',') if p.strip()}
    no_store = 'no-store' in cc_parts
    no_cache = 'no-cache' in cc_parts
    max_age = None
    for p in cc_parts:
        if p.startswith('max-age='):
            max_age = int(p.split('=', 1)[1])

    headers = {'ETag': resource_etag, 'Cache-Control': cache_control}
    if vary_headers:
        headers['Vary'] = ', '.join(sorted(vary_headers.keys()))

    inm = norm_req.get('if-none-match', '')
    etags = [t.strip() for t in inm.split(',') if t.strip()]
    if not no_store and ('*' in etags or resource_etag in etags):
        return {
            'status': 304,
            'body': '',
            'headers': headers,
            'cacheable': True,
            'must_revalidate': no_cache,
            'max_age': max_age,
        }

    return {
        'status': 200,
        'body': resource_body,
        'headers': headers,
        'cacheable': not no_store,
        'must_revalidate': no_cache,
        'max_age': max_age,
    }

