def negotiate_media_type(accept_header: str, available: list[str]) -> str | None:
    if not accept_header.strip():
        return available[0] if available else None
    parsed = []
    excluded = set()
    for item in accept_header.split(','):
        parts = [p.strip() for p in item.split(';') if p.strip()]
        if not parts:
            continue
        mime = parts[0].lower()
        q = 1.0
        for p in parts[1:]:
            if p.lower().startswith('q='):
                q = float(p.split('=', 1)[1])
        if q == 0:
            excluded.add(mime)
        elif q > 0:
            parsed.append((mime, q))

    best = None
    best_score = (-1.0, -1)
    for cand in available:
        c_low = cand.lower()
        if c_low in excluded:
            continue
        c_type = c_low.split('/')[0]
        for mime, q in parsed:
            if mime == c_low:
                spec = 3
            elif mime == f'{c_type}/*':
                spec = 2
            elif mime == '*/*':
                spec = 1
            else:
                continue
            score = (q, spec)
            if score > best_score:
                best_score = score
                best = cand
    return best

def build_safe_headers(raw_headers: dict[str, str]) -> dict[str, str]:
    safe = {}
    for k, v in raw_headers.items():
        if '\r' in k or '\n' in k or '\r' in v or '\n' in v:
            raise ValueError('CRLF injection detected in HTTP header')
        safe[k.strip().lower()] = v.strip()
    return safe

