def _match_san(pattern: str, hostname: str) -> bool:
    p = pattern.lower()
    h = hostname.lower()
    if p == h:
        return True
    if p.startswith('*.'):
        suffix = p[2:]
        if '.' in h and h.endswith('.' + suffix):
            prefix = h[:-(len(suffix) + 1)]
            return '.' not in prefix and len(prefix) > 0
    return False

def validate_cert_chain(chain: list[dict], trusted_cas: set[str], hostname: str, now_ts: int) -> dict:
    if not chain:
        return {'valid': False, 'reason': 'empty_chain'}
    for cert in chain:
        if not (cert['not_before'] <= now_ts <= cert['not_after']):
            return {'valid': False, 'reason': 'expired_or_not_yet_valid'}
    for i in range(len(chain) - 1):
        if chain[i]['issuer'] != chain[i + 1]['subject']:
            return {'valid': False, 'reason': 'broken_chain'}
    root_issuer = chain[-1]['issuer']
    if chain[-1]['subject'] not in trusted_cas and root_issuer not in trusted_cas:
        return {'valid': False, 'reason': 'untrusted_root'}
    leaf_sans = chain[0].get('san', [])
    if not any(_match_san(s, hostname) for s in leaf_sans):
        return {'valid': False, 'reason': 'hostname_mismatch'}
    return {'valid': True, 'reason': 'ok'}

