def simulate_http_transfer(requests: list[dict], protocol: str, max_h1_conns: int = 6) -> dict:
    if not requests:
        return {'total_ms': 0, 'connections': 0, 'completion_order': []}
    if protocol == 'HTTP/1.1':
        conns = [0] * max(1, max_h1_conns)
        finished = []
        for req in requests:
            idx = min(range(len(conns)), key=lambda i: conns[i])
            conns[idx] += req['duration_ms']
            finished.append((conns[idx], req['id']))
        finished.sort()
        return {
            'total_ms': max(conns),
            'connections': min(len(requests), max_h1_conns),
            'completion_order': [rid for _, rid in finished],
        }
    if protocol == 'HTTP/2':
        ordered = sorted(requests, key=lambda r: (r['duration_ms'], r.get('priority', 10), r['id']))
        return {
            'total_ms': max(r['duration_ms'] for r in requests),
            'connections': 1,
            'completion_order': [r['id'] for r in ordered],
        }
    raise ValueError(f'Unknown protocol: {protocol}')

