class HPACKTable:
    STATIC = [(':method', 'GET'), (':scheme', 'https'), (':path', '/')]

    def __init__(self, max_bytes: int = 128):
        self.max_bytes = max_bytes
        self.dynamic = []

    @staticmethod
    def _entry_size(name: str, val: str) -> int:
        return len(name) + len(val) + 32

    def _current_bytes(self) -> int:
        return sum(self._entry_size(k, v) for k, v in self.dynamic)

    def _insert_dynamic(self, name: str, val: str):
        sz = self._entry_size(name, val)
        if sz > self.max_bytes:
            self.dynamic.clear()
            return
        self.dynamic.insert(0, (name, val))
        while self._current_bytes() > self.max_bytes:
            self.dynamic.pop()

    def encode(self, headers: list[tuple[str, str]]) -> list[tuple]:
        out = []
        for k, v in headers:
            if (k, v) in self.STATIC:
                out.append(('indexed', self.STATIC.index((k, v)) + 1))
            elif (k, v) in self.dynamic:
                out.append(('indexed', len(self.STATIC) + self.dynamic.index((k, v)) + 1))
            else:
                out.append(('literal', k, v))
                self._insert_dynamic(k, v)
        return out

