    digest = hashlib.sha1((key + WS_GUID).encode('utf-8')).digest()
    accept = base64.b64encode(digest).decode('ascii')
    return {
        'status': 101,
        'headers': {
            'Upgrade': 'websocket',
            'Connection': 'Upgrade',
            'Sec-WebSocket-Accept': accept,
        },
    }

