import struct

def encode_ws_frame(payload: bytes, opcode: int = 1, mask_key: bytes | None = None) -> bytes:
    b0 = 0x80 | (opcode & 0x0F)
    length = len(payload)
    mask_bit = 0x80 if mask_key is not None else 0x00
    out = bytearray([b0])
    if length <= 125:
        out.append(mask_bit | length)
    elif length <= 65535:
        out.append(mask_bit | 126)
        out.extend(struct.pack('>H', length))
    else:
        raise ValueError('Payload too large for this exercise')
    if mask_key is not None:
        if len(mask_key) != 4:
            raise ValueError('mask_key must be 4 bytes')
        out.extend(mask_key)
        out.extend(bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload)))
    else:
        out.extend(payload)
    return bytes(out)

def decode_ws_frame(raw: bytes) -> dict:
    b0, b1 = raw[0], raw[1]
    fin = bool(b0 & 0x80)
    opcode = b0 & 0x0F
    masked = bool(b1 & 0x80)
    length = b1 & 0x7F
    idx = 2
    if length == 126:
        length = struct.unpack('>H', raw[idx:idx + 2])[0]
        idx += 2
    mask_key = None
    if masked:
        mask_key = raw[idx:idx + 4]
        idx += 4
    data = raw[idx:idx + length]
    if masked:
        data = bytes(b ^ mask_key[i % 4] for i, b in enumerate(data))
    return {'fin': fin, 'opcode': opcode, 'masked': masked, 'payload': data}

