class WSBroker:
    def __init__(self, heartbeat_timeout: int = 30, max_queue: int = 3):
        self.heartbeat_timeout = heartbeat_timeout
        self.max_queue = max_queue
        self.clients = {}

    def connect(self, cid: str, now: int):
        self.clients[cid] = {'last_pong': now, 'queue': []}

    def pong(self, cid: str, now: int):
        if cid in self.clients:
            self.clients[cid]['last_pong'] = now

    def disconnect(self, cid: str):
        self.clients.pop(cid, None)

    def sweep_stale(self, now: int) -> list[str]:
        stale = [cid for cid, c in self.clients.items() if now - c['last_pong'] > self.heartbeat_timeout]
        for cid in stale:
            self.disconnect(cid)
        return stale

    def broadcast(self, msg: str, now: int) -> dict:
        dropped = []
        for cid in self.sweep_stale(now):
            dropped.append((cid, 'heartbeat_timeout'))
        delivered = 0
        for cid in list(self.clients.keys()):
            q = self.clients[cid]['queue']
            if len(q) >= self.max_queue:
                self.disconnect(cid)
                dropped.append((cid, 'slow_consumer'))
            else:
                q.append(msg)
                delivered += 1
        return {'delivered': delivered, 'dropped': dropped}

