async def asgi_app(scope, receive, send):
    if scope['type'] == 'lifespan':
        while True:
            msg = await receive()
            if msg['type'] == 'lifespan.startup':
                await send({'type': 'lifespan.startup.complete'})
            elif msg['type'] == 'lifespan.shutdown':
                await send({'type': 'lifespan.shutdown.complete'})
                return
    elif scope['type'] == 'http':
        body = bytearray()
        while True:
            msg = await receive()
            body.extend(msg.get('body', b''))
            if not msg.get('more_body', False):
                break
        await send({'type': 'http.response.start', 'status': 200, 'headers': [(b'content-type', b'text/plain')]})
        await send({'type': 'http.response.body', 'body': bytes(body).upper(), 'more_body': False})

def timing_middleware(app, clock):
    async def wrapper(scope, receive, send):
        if scope['type'] != 'http':
            await app(scope, receive, send)
            return
        t0 = clock()
        async def wrapped_send(msg):
            if msg['type'] == 'http.response.start':
                elapsed = f'{clock() - t0:.3f}'.encode('ascii')
                headers = list(msg.get('headers', []))
                headers.append((b'x-process-time', elapsed))
                msg = {**msg, 'headers': headers}
            await send(msg)
        await app(scope, receive, wrapped_send)
    return wrapper

