class _ClosingWrapper:
    def __init__(self, chunks, orig_iter):
        self._chunks = iter(chunks)
        self._orig_iter = orig_iter

    def __iter__(self):
        return self

    def __next__(self):
        return next(self._chunks)

    def close(self):
        if hasattr(self._orig_iter, 'close'):
            self._orig_iter.close()

class Utf8LengthMiddleware:
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        captured = {}
        def custom_start_response(status, headers, exc_info=None):
            captured['status'] = status
            captured['headers'] = list(headers)
            captured['exc_info'] = exc_info
            return lambda x: None

        orig_iter = self.app(environ, custom_start_response)
        try:
            chunks = list(orig_iter)
        except Exception:
            if hasattr(orig_iter, 'close'):
                orig_iter.close()
            raise
        total_bytes = sum(len(c) for c in chunks)
        new_headers = [(k, v) for k, v in captured['headers'] if k.lower() != 'content-length']
        new_headers.append(('Content-Length', str(total_bytes)))
        start_response(captured['status'], new_headers, captured['exc_info'])
        return _ClosingWrapper(chunks, orig_iter)

