def audit_rest_maturity(spec: dict) -> dict:
    if spec.get('single_rpc_endpoint') or not spec.get('uses_resource_uris'):
        level = 0
    elif not spec.get('uses_http_verbs'):
        level = 1
    elif not spec.get('has_hypermedia_links'):
        level = 2
    else:
        level = 3

    violations = []
    if level == 0:
        violations.append('rpc_tunneling')
    if spec.get('stores_session_state'):
        violations.append('stateful_server')

    return {'level': level, 'violations': violations, 'is_stateless': not spec.get('stores_session_state')}

