def _project(selection: dict, node):
    if node is None:
        return None
    if isinstance(node, list):
        return [_project(selection, item) for item in node]
    out = {}
    for key, sub in selection.items():
        if key not in node:
            out[key] = None
        elif sub is True:
            out[key] = node[key]
        elif isinstance(sub, dict):
            out[key] = _project(sub, node[key])
    return out

def resolve_graphql(query: dict, data: dict) -> dict:
    return _project(query, data)

