def validate_graphql_limits(query: dict, max_depth: int, max_cost: int, field_costs: dict | None = None) -> dict:
    costs_map = field_costs or {}

    def walk(node: dict, depth: int) -> tuple[int, int]:
        if not node:
            return depth, 0
        max_d = depth
        total_c = 0
        for k, v in node.items():
            total_c += costs_map.get(k, 1)
            if isinstance(v, dict):
                sub_d, sub_c = walk(v, depth + 1)
                if sub_d > max_d:
                    max_d = sub_d
                total_c += sub_c
        return max_d, total_c

    depth, cost = walk(query, 1) if query else (0, 0)
    reasons = []
    if depth > max_depth:
        reasons.append('max_depth_exceeded')
    if cost > max_cost:
        reasons.append('max_cost_exceeded')
    return {'allowed': len(reasons) == 0, 'depth': depth, 'cost': cost, 'reasons': reasons}

