def _coerce(val: str, sample):
    if isinstance(sample, int) and not isinstance(sample, bool):
        return int(val)
    return val

def query_collection(items: list[dict], params: dict) -> list[dict]:
    res = list(items)
    for k, raw_v in params.items():
        if k in ('sort', 'fields'):
            continue
        if '__' in k:
            field, op = k.split('__', 1)
        else:
            field, op = k, 'eq'
        sample = next((it[field] for it in items if field in it), None)
        if op == 'eq':
            target = _coerce(str(raw_v), sample)
            res = [it for it in res if it.get(field) == target]
        elif op == 'gte':
            target = _coerce(str(raw_v), sample)
            res = [it for it in res if it.get(field) >= target]
        elif op == 'lte':
            target = _coerce(str(raw_v), sample)
            res = [it for it in res if it.get(field) <= target]
        elif op == 'in':
            targets = {_coerce(x.strip(), sample) for x in str(raw_v).split(',') if x.strip()}
            res = [it for it in res if it.get(field) in targets]

    sort_param = params.get('sort')
    if sort_param:
        for key in reversed([s.strip() for s in sort_param.split(',') if s.strip()]):
            desc = key.startswith('-')
            fname = key[1:] if desc else key
            res.sort(key=lambda it: it.get(fname), reverse=desc)

    fields_param = params.get('fields')
    if fields_param:
        keep = [f.strip() for f in fields_param.split(',') if f.strip()]
        res = [{f: it[f] for f in keep if f in it} for it in res]
    else:
        res = [dict(it) for it in res]
    return res

