def route_api_version(path: str, headers: dict, versions_cfg: dict, now_ts: int) -> dict:
    ver = None
    parts = [p for p in path.split('/') if p]
    if parts and parts[0].startswith('v') and parts[0][1:].isdigit():
        ver = parts[0]
    else:
        norm_h = {k.lower(): v for k, v in headers.items()}
        ver = norm_h.get('accept-version')

    cfg = versions_cfg.get(ver)
    if not cfg:
        return {'status': 404, 'version': ver, 'headers': {}}
    if cfg['status'] == 'retired':
        return {'status': 410, 'version': ver, 'headers': {}}

    resp_headers = {}
    if cfg['status'] == 'deprecated':
        resp_headers['Deprecation'] = 'true'
        if cfg.get('sunset'):
            resp_headers['Sunset'] = cfg['sunset']
        if cfg.get('successor'):
            succ = cfg['successor']
            resp_headers['Link'] = f'<{succ}>; rel="successor-version"'
