def detect_breaking_changes(old_spec: dict, new_spec: dict) -> list[str]:
    issues = []
    for path, methods in old_spec.items():
        if path not in new_spec:
            for m in methods:
                issues.append(f'removed_endpoint:{path}:{m}')
            continue
        for m, old_op in methods.items():
            if m not in new_spec[path]:
                issues.append(f'removed_endpoint:{path}:{m}')
                continue
            new_op = new_spec[path][m]
            old_req = set(old_op.get('required_fields', []))
            new_req = set(new_op.get('required_fields', []))
            for f in new_req - old_req:
                issues.append(f'new_required_field:{path}:{m}:{f}')
            old_fields = old_op.get('fields', {})
            new_fields = new_op.get('fields', {})
            for f, old_t in old_fields.items():
                if f in new_fields and new_fields[f] != old_t:
                    issues.append(f'type_changed:{path}:{m}:{f}')
            old_enums = old_op.get('enums', {})
            new_enums = new_op.get('enums', {})
            for f, old_vals in old_enums.items():
                if f in new_enums:
                    for val in set(old_vals) - set(new_enums[f]):
                        issues.append(f'enum_narrowed:{path}:{m}:{f}:{val}')
    return sorted(issues)

