class IdempotencyStore:
    def __init__(self, ttl: int = 60):
        self.ttl = ttl
        self.records = {}

    def mark_in_progress(self, key: str, payload_hash: str, now: int):
        self.records[key] = {'state': 'in_progress', 'hash': payload_hash, 'expires_at': now + self.ttl}

    def process(self, key: str, payload_hash: str, now: int, executor) -> tuple[int, dict]:
        rec = self.records.get(key)
        if rec and now >= rec['expires_at']:
            self.records.pop(key, None)
            rec = None
        if rec:
            if rec['hash'] != payload_hash:
                return 422, {'error': 'Idempotency-Key reused with different payload'}
            if rec['state'] == 'in_progress':
                return 409, {'error': 'Request already in progress'}
            return 200, rec['response']

        self.mark_in_progress(key, payload_hash, now)
        try:
            resp = executor()
        except Exception:
            self.records.pop(key, None)
            raise
        self.records[key] = {'state': 'done', 'hash': payload_hash, 'response': resp, 'expires_at': now + self.ttl}
        return 201, resp

