import hashlib
import hmac

class WebhookReceiver:
    def __init__(self, secret: bytes, max_skew_sec: int = 300):
        self.secret = secret
        self.max_skew_sec = max_skew_sec
        self.processed = set()

    def receive(self, event_id: str, ts: int, body: bytes, signature: str, now_ts: int) -> dict:
        if abs(now_ts - ts) > self.max_skew_sec:
            return {'status': 400, 'reason': 'timestamp_out_of_window', 'duplicate': False}
        expected = hmac.new(self.secret, f'{ts}.'.encode('utf-8') + body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            return {'status': 401, 'reason': 'invalid_signature', 'duplicate': False}
        if event_id in self.processed:
            return {'status': 200, 'reason': 'ok', 'duplicate': True}
        self.processed.add(event_id)
        return {'status': 200, 'reason': 'ok', 'duplicate': False}

