import sqlite3

def fetch_keyset_page(conn: sqlite3.Connection, limit: int, cursor: tuple[str, int] | None = None) -> dict:
    if cursor is None:
        rows = conn.execute(
            'SELECT id, created_at, title FROM events ORDER BY created_at DESC, id DESC LIMIT ?',
            (limit + 1,),
        ).fetchall()
    else:
        c_ts, c_id = cursor
        rows = conn.execute(
            'SELECT id, created_at, title FROM events '
            'WHERE created_at < ? OR (created_at = ? AND id < ?) '
            'ORDER BY created_at DESC, id DESC LIMIT ?',
            (c_ts, c_ts, c_id, limit + 1),
        ).fetchall()

    has_more = len(rows) > limit
    page_rows = rows[:limit]
    items = [{'id': r[0], 'created_at': r[1], 'title': r[2]} for r in page_rows]
    next_cursor = (items[-1]['created_at'], items[-1]['id']) if has_more and items else None
    return {'items': items, 'next_cursor': next_cursor, 'has_more': has_more}

