def handle_cors_preflight(method: str, headers: dict, policy: dict) -> dict:
    norm = {k.lower(): v for k, v in headers.items()}
    origin = norm.get('origin')
    if not origin or origin not in policy['allowed_origins']:
        return {'status': 403, 'headers': {}}
    if method.upper() != 'OPTIONS' or 'access-control-request-method' not in norm:
        return {'status': 200, 'headers': {'Access-Control-Allow-Origin': origin, 'Vary': 'Origin'}}

    req_method = norm['access-control-request-method'].strip().upper()
    if req_method not in policy['allowed_methods']:
        return {'status': 403, 'headers': {}}

    raw_hdrs = norm.get('access-control-request-headers', '')
    req_hdrs = [h.strip().lower() for h in raw_hdrs.split(',') if h.strip()]
    if any(h not in policy['allowed_headers'] for h in req_hdrs):
        return {'status': 403, 'headers': {}}

    return {
        'status': 204,
        'headers': {
            'Access-Control-Allow-Origin': origin,
            'Access-Control-Allow-Methods': ', '.join(sorted(policy['allowed_methods'])),
            'Access-Control-Allow-Headers': ', '.join(sorted(policy['allowed_headers'])),
            'Access-Control-Max-Age': str(policy.get('max_age', 600)),
            'Vary': 'Origin',
        },
    }

