import hmac
from urllib.parse import urlparse

def verify_csrf(method: str, headers: dict, cookies: dict, allowed_origin: str) -> bool:
    if method.upper() in ('GET', 'HEAD', 'OPTIONS'):
        return True
    norm_h = {k.lower(): v for k, v in headers.items()}
    origin = norm_h.get('origin')
    referer = norm_h.get('referer')
    if origin:
        if origin != allowed_origin:
            return False
    elif referer:
        parsed = urlparse(referer)
        ref_origin = f'{parsed.scheme}://{parsed.netloc}'
        if ref_origin != allowed_origin:
            return False
    else:
        return False

    hdr_tok = norm_h.get('x-csrf-token', '')
    ck_tok = cookies.get('csrf_token', '')
    if not hdr_tok or not ck_tok:
        return False
    return hmac.compare_digest(hdr_tok, ck_tok)

