def build_strict_csp(nonce: str, cdn_hosts: list[str] | None = None) -> str:
    scripts = ["'self'", f"'nonce-{nonce}'"]
    if cdn_hosts:
        scripts.extend(cdn_hosts)
    return f"default-src 'self'; script-src {' '.join(scripts)}; object-src 'none'; base-uri 'self'"

def audit_csp(policy: str) -> list[str]:
    directives = {}
    for part in policy.split(';'):
        tokens = part.strip().split()
        if tokens:
            directives[tokens[0].lower()] = tokens[1:]
    issues = []
    all_vals = [v for vals in directives.values() for v in vals]
    if "'unsafe-inline'" in all_vals:
        issues.append('unsafe_inline')
    if "'unsafe-eval'" in all_vals:
        issues.append('unsafe_eval')
    if '*' in all_vals:
        issues.append('wildcard_source')
    if directives.get('object-src') != ["'none'"]:
        issues.append('missing_object_src_none')
    return sorted(issues)

