        raise ValueError(f'Invalid sort column: {sort_by}')
    dir_up = sort_dir.upper()
    if dir_up not in ALLOWED_DIRS:
        raise ValueError(f'Invalid sort direction: {sort_dir}')
    sql = f'SELECT id, name, price FROM products WHERE category = ? ORDER BY {sort_by} {dir_up}'
    return conn.execute(sql, (category,)).fetchall()

