import sqlite3

class SafeQueryBuilder:
    def __init__(self, allowed_tables: dict[str, set[str]]):
        self.allowed_tables = allowed_tables
        self.template_cache = {}

    def select(self, conn: sqlite3.Connection, table: str, columns: list[str], filters: dict) -> list[dict]:
        if table not in self.allowed_tables:
            raise ValueError(f'Disallowed table: {table}')
        allowed_cols = self.allowed_tables[table]
        if not columns or any(c not in allowed_cols for c in columns):
            raise ValueError('Disallowed column in projection')
        filter_keys = sorted(filters.keys())
        if any(k not in allowed_cols for k in filter_keys):
            raise ValueError('Disallowed column in filters')

        cache_key = (table, tuple(columns), tuple(filter_keys))
        sql = self.template_cache.get(cache_key)
        if sql is None:
            cols_sql = ', '.join(columns)
            if filter_keys:
                where_sql = ' AND '.join(f'{k} = ?' for k in filter_keys)
                sql = f'SELECT {cols_sql} FROM {table} WHERE {where_sql}'
            else:
                sql = f'SELECT {cols_sql} FROM {table}'
            self.template_cache[cache_key] = sql

        params = tuple(filters[k] for k in filter_keys)
        rows = conn.execute(sql, params).fetchall()
        return [dict(zip(columns, row)) for row in rows]

